#!/bin/bash
# Baut index.html für GitHub Pages (mit App-Funktion) aus der Artefakt-Datei
S="$(cd "$(dirname "$0")/.." && pwd)/quelle"
STAND=$(date +%Y%m%d%H%M)
cd "$(dirname "$0")/.."
{ printf '<!doctype html>\n<html lang="de">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<style>body{margin:0}img{max-width:100%%}[hidden]{display:none!important}#qw-neu{position:fixed;left:50%%;bottom:18px;transform:translateX(-50%%);background:#3e6b2a;color:#fff;font:600 15px system-ui,sans-serif;padding:10px 18px;border-radius:999px;box-shadow:0 4px 16px rgba(0,0,0,.25);z-index:999}</style>\n<meta name="description" content="Quellwissen – Kompendium für Natur, Selbstversorgung und Gesundheit: Pflanzen, Boden, Mischkultur, Knospen, Tabak, Hanf, Getreide & Brot, Biochemie, Autoren">\n<link rel="manifest" href="manifest.webmanifest">\n<meta name="theme-color" content="#3e6b2a">\n<link rel="icon" href="icon-192.png">\n<link rel="apple-touch-icon" href="apple-touch-icon.png">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-title" content="Quellwissen">\n<meta name="apple-mobile-web-app-status-bar-style" content="default">\n<meta name="qw-stand" content="%s">\n<script>\nif("serviceWorker" in navigator){addEventListener("load",function(){navigator.serviceWorker.register("sw.js").catch(function(){});});}\naddEventListener("load",function(){try{var s=document.querySelector("meta[name=qw-stand]").content,a=localStorage.getItem("qw-stand");if(a&&a!==s){var d=document.createElement("div");d.id="qw-neu";d.textContent="Neue Version geladen";document.body.appendChild(d);setTimeout(function(){d.remove();},4000);}localStorage.setItem("qw-stand",s);}catch(e){}});\n</script>\n' "$STAND"; cat $S/gruenwissen.html; } > index.html
